package app.dayflow.markdown;import org.json.*;import android.content.Context;
final class Data {private static Data instance;private final MainActivity activity;private JSONObject note;private Data(MainActivity a,JSONObject r){activity=a;note=r;}static void attach(MainActivity a,JSONObject r){instance=new Data(a,r);}static Data get(Context c){return instance;}JSONObject find(String id)throws JSONException{return note.optString("id").equals(id)?new JSONObject(note.toString()):null;}void save(JSONObject r)throws Exception{activity.wrote(r);note=new JSONObject(r.toString());}static void validate(JSONObject r)throws Exception{if(r.optString("title").length()>1000)throw new Exception("标题过长");}}
